export class PublicApi extends BaseAPI {
  /**
   * Available only if env `STROLTM_LOG_LEVEL=DEBUG` or `STROLTM_LOG_LEVEL=TRACE`
   *
   * @param {any} [options] Override http request option.
   * @throws {RequiredError}
   * @summary Go debug info
   */
  public getDebug(options?: RawAxiosRequestConfig) {
    return PublicApiFp(this.configuration)
      .getDebug(options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * @param {any} [options] Override http request option.
   * @throws {RequiredError}
   * @summary Prometheus metrics
   */
  public getMetrics(options?: RawAxiosRequestConfig) {
    return PublicApiFp(this.configuration)
      .getMetrics(options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * @param {any} [options] Override http request option.
   * @throws {RequiredError}
   * @summary Ping
   */
  public ping(options?: RawAxiosRequestConfig) {
    return PublicApiFp(this.configuration)
      .ping(options)
      .then((request) => request(this.axios, this.basePath));
  }
}
